WITH base AS (
  SELECT "NCT", "PubMed ID" AS "PMID", "Author" AS "Author", "Year", "Cancer type", "Type of combination", "Monotherapy/combination"
  FROM compat.clinical_trials
  WHERE LOWER("Cancer type") LIKE '%melanoma%' AND LOWER("Monotherapy/combination") LIKE '%combination%'
)
SELECT * FROM base;
